import{_ as r,o as l,c as o,a2 as a}from"./chunks/framework.aJDz64y9.js";const _=JSON.parse('{"title":"Серая работа: механики и наводчики","description":"","frontmatter":{},"headers":[],"relativePath":"crime/grey-work.md","filePath":"crime/grey-work.md","lastUpdated":1794540927000}'),e={name:"crime/grey-work.md"};function i(d,t,n,s,g,h){return l(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="серая-работа-механики-и-наводчики" tabindex="-1">Серая работа: механики и наводчики <a class="header-anchor" href="#серая-работа-механики-и-наводчики" aria-label="Permalink to &quot;Серая работа: механики и наводчики&quot;">​</a></h1><p>Работа «налево» разрешена, но оставляет следы: у каждой серой услуги есть тот, кто за неё отвечает, счётчик подозрения и законный повод для проверки.</p><table tabindex="0"><thead><tr><th>Кто</th><th>Что продаёт</th><th>Что его выдаёт</th><th>Чем рискует</th></tr></thead><tbody><tr><td>Механик СТО</td><td>Поиск жучков, перебивку VIN, номера, разбор</td><td>Журнал подъёмника, срезанные таблички в мусоре, расход спецматериалов</td><td>Статья за соучастие, увольнение</td></tr><tr><td>Владелец СТО</td><td>Доступ к подъёмнику и спецматериалам</td><td>Счётчик подозрения его бизнеса</td><td>Штраф бизнесу, изъятие материалов, приостановка лицензии на 1–3 дня</td></tr><tr><td>Курьер, таксист, электрик, уборщик</td><td>«Заметку о доме» с адресом и наблюдением</td><td>Скрытый номер работника в заметке, статистика обнесённых адресов</td><td>Статья за соучастие, увольнение, закрытый доступ к работе на несколько дней</td></tr></tbody></table><h2 id="как-это-устроено-на-сто" tabindex="-1">Как это устроено на СТО <a class="header-anchor" href="#как-это-устроено-на-сто" aria-label="Permalink to &quot;Как это устроено на СТО&quot;">​</a></h2><ol><li><strong>Политика владельца.</strong> Владелец выбирает один из трёх режимов. <ul><li>Запрещено: серые услуги на подъёмниках этого СТО отключены.</li><li>Разрешено: спецматериалы берутся со склада СТО, и владелец получает долю через их цену.</li><li>На свой страх: механик приносит материалы сам. Владелец доли не получает, но его бизнес всё равно копит подозрение.</li></ul></li><li><strong>Спецматериалы.</strong> Серая услуга расходует заготовки VIN-табличек, чистые пластины номеров и расходники сканера. Их покупают у барыги или у мастера.</li><li><strong>Работа.</strong> Механик проходит мини-игры на подъёмнике. Цену с клиентом он назначает сам; ориентир — 15–25% экспортной цены машины.</li><li><strong>След.</strong> Подъёмник ведёт журнал: легальный заказ идёт с нарядом, серый — как неучтённые минуты. Срезанные таблички падают в мусорный бак предметом-уликой. Вывоз мусора на свалку — отдельная короткая задача для механика.</li><li><strong>Подозрение.</strong> Каждая серая услуга повышает счётчик подозрения СТО, сильнее всего — машина с работающим жучком, заехавшая в бокс. Легальные заказы и время счётчик снижают.</li></ol><p>У счётчика подозрения три порога.</p><ul><li><strong>Слухи.</strong> Наводчики-NPC начинают советовать это СТО угонщикам: клиентов становится больше.</li><li><strong>Ориентировка.</strong> Полиция получает в диспетчерской основание на одну проверку без ордера.</li><li><strong>Под колпаком.</strong> Проверки становятся регулярными, а следующее подтверждённое нарушение приостанавливает лицензию.</li></ul><p>На проверке у полиции три действия: осмотреть машину на подъёмнике, открыть журнал подъёмника, обыскать мусорный бак и склад.</p><h2 id="как-это-устроено-у-наводчиков" tabindex="-1">Как это устроено у наводчиков <a class="header-anchor" href="#как-это-устроено-у-наводчиков" aria-label="Permalink to &quot;Как это устроено у наводчиков&quot;">​</a></h2><ul><li><strong>Заметка.</strong> За смену работник получает не больше двух заметок. Заметка живёт 3–6 часов и передаётся только из рук в руки. Ориентир цены — 5–10% ожидаемой добычи.</li><li><strong>След в предмете.</strong> В заметке скрыт номер работника. Найденная у задержанного или в его тайнике, она становится уликой против наводчика.</li><li><strong>След в статистике.</strong> Если адреса одного работника трижды за неделю обносят в течение суток после его смены, в диспетчерскую падает ориентировка на него.</li><li><strong>Последствия.</strong> Работодатель увольняет, доступ к этой работе закрывается на несколько дней, дело идёт как соучастие.</li></ul><p>Серый заработок выгоден, пока он редкий: чем чаще человек подрабатывает, тем быстрее растёт подозрение. Поэтому запрет не нужен: систему держат следы и риск.</p>',11)])])}const p=r(e,[["render",i]]);export{_ as __pageData,p as default};
